/**
 * 다른 플레이어 표시: 복셀 인형(머리·몸·팔·다리) + 머리 위 이름.
 * 서버 위치(20Hz)를 받아 부드럽게 따라간다 (지수 보간, 약 100ms 지연).
 * 인형 생김새는 `render/playerModel.ts` — 얼굴·머리카락·손·신발이 있고 색 16가지마다 다른 사람이다 (#86).
 */
import { blockOf, CAMEL_BACK, CAMEL_SEAT_Y, DOOR_DIR, FLAG_RIDING, FLAG_SNEAK, type PlayerInfo, type PlayerStateEntry, type RidingInfo, type SepBody, skyOf, type SleepInfo } from '@dragon-village/shared';
import { mountMesh, mountSeat } from '../render/DragonMesh';
import { sanitizeEquipment } from '@dragon-village/shared';
import { COMBAT } from '@dragon-village/shared/data';
import { armorVoxels, shieldVoxels } from '../render/armorModel';
import { PART_AT, PLAYER_SHADES, VOXEL, paletteFor, playerVoxels } from '../render/playerModel';
import { type Voxel, buildVoxelGeometry } from '../render/voxelGeometry';
import * as THREE from 'three';

interface Figure {
  info: PlayerInfo;
  group: THREE.Group;
  body: THREE.Group;
  label: THREE.Sprite;
  target: { x: number; y: number; z: number; yaw: number; pitch: number; flags: number };
  cur: { x: number; y: number; z: number; yaw: number };
  torso: THREE.Mesh;
  head: THREE.Mesh;
  legL: THREE.Mesh;
  legR: THREE.Mesh;
  armL: THREE.Mesh;
  armR: THREE.Mesh;
  /** 오른손에 든 것 (아이콘 판, #96) */
  held: THREE.Mesh | null;
  /** 입은 갑옷 껍질·방패 (M8-2). 부위 메시의 자식 */
  armor: THREE.Mesh[];
  walk: number;
  /** 🛡️ 막는 중 (#144): 왼팔을 앞으로 올려 방패가 몸 앞에 온다 */
  guarding: boolean;
  /** 침대에 누움 (#204): 등을 대고 머리는 머리판 쪽 */
  sleeping: SleepInfo | null;
  lastMove: number;
  bubble: { sprite: THREE.Sprite; until: number } | null;
  /** 타고 있는 드래곤 (M6-4) */
  mount: THREE.Mesh | null;
  /** 탄 것 (낙타 뒷자리 찾기용, 2026-11-07) */
  riding: RidingInfo | null;
  /** 여섯 부위가 같이 쓰는 재질. 주변 빛을 여기 색으로 준다 (#86) */
  material: THREE.MeshBasicMaterial;
  /** 지금 밝기 (빛이 뚝뚝 끊기지 않게 부드럽게 따라간다) */
  lum: number;
}

/** 동굴에서도 아주 조금은 보이게 (블록 셰이더와 같은 값) */
const MIN_LUM = 0.05;
/** 횃불빛이 스카이라이트보다 셀 때 섞는 따뜻한 색 (블록 셰이더와 같다) */
const WARM = new THREE.Color(1.0, 0.86, 0.68);
/** 계산에 돌려 쓰는 색 (프레임마다 새로 만들지 않게) */
const TINT = new THREE.Color();

/** 칸 하나의 빛 → 밝기·색. 블록 셰이더(ChunkMaterial)와 같은 곡선이라 사람과 세계가 따로 놀지 않는다 */
function lightColor(packed: number, skyLight: number, out: THREE.Color): number {
  const sky = (skyOf(packed) / 15) * skyLight;
  const blk = blockOf(packed) / 15;
  const lum = MIN_LUM + (1 - MIN_LUM) * Math.pow(Math.max(sky, blk), 1.5);
  out.set(0xffffff).lerp(WARM, Math.max(0, Math.min(1, blk - sky)));
  return lum;
}

/** 인형 키 (복셀 32칸 = 몸 판정과 같은 1.8). 이름표·말풍선 높이의 기준 */
const FIGURE_H = 32 * VOXEL;
/** 앉은 자세 (#192): 다리 길이(12칸)만큼 내려앉고, 다리는 앞으로 거의 수평, 팔은 조금 앞으로 */
const SIT_DROP = 12 * VOXEL;
const SIT_LEG = Math.PI / 2; // 인형 앞이 -z 라 +가 앞. 정확히 90° — 몸은 수직, 다리는 수평 (아들 2026-10-19)
const SIT_ARM = 0.6;

/**
 * 부위 복셀 → 메시. buildVoxelGeometry 는 드래곤(홀수 폭, x 대칭)에 맞춰 반 칸 옮기므로,
 * 짝수 폭인 사람 부위는 그만큼 되돌려야 가운데가 맞는다.
 */
function partMesh(voxels: readonly Voxel[], material: THREE.Material): THREE.Mesh {
  const geom = buildVoxelGeometry(voxels, VOXEL, PLAYER_SHADES);
  geom.translate(VOXEL / 2, 0, VOXEL / 2);
  return new THREE.Mesh(geom, material);
}

export function nameSprite(text: string, bg = 'rgba(0,0,0,0.45)', scale = 0.55): THREE.Sprite {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d')!;
  ctx.font = 'bold 40px system-ui, sans-serif';
  const w = Math.ceil(ctx.measureText(text).width) + 32;
  canvas.width = w;
  canvas.height = 56;
  ctx.font = 'bold 40px system-ui, sans-serif';
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, w, 56);
  ctx.fillStyle = '#fff';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, 16, 30);
  const tex = new THREE.CanvasTexture(canvas);
  tex.minFilter = THREE.LinearFilter;
  const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, depthTest: true, transparent: true }));
  sprite.scale.set((w / 56) * scale, scale, 1);
  return sprite;
}

export class RemotePlayers {
  readonly group = new THREE.Group();
  private readonly figures = new Map<number, Figure>();
  /** 아이템 id → 아이콘 캔버스 (Game 이 준다). 없으면 손에 든 것을 안 그린다 */
  iconOf: ((id: string) => HTMLCanvasElement | null) | null = null;

  constructor(scene: THREE.Scene) {
    scene.add(this.group);
  }

  get count(): number {
    return this.figures.size;
  }

  upsert(info: PlayerInfo): void {
    this.remove(info.idx);
    const v = playerVoxels(paletteFor(info.color));
    const material = new THREE.MeshBasicMaterial({ vertexColors: true });
    const group = new THREE.Group();
    const body = new THREE.Group();
    // 팔·다리는 붙이는 자리가 곧 회전축(어깨·엉덩이)이라 걸을 때 제대로 흔들린다
    const at = (m: THREE.Mesh, spot: readonly [number, number]): THREE.Mesh => {
      m.position.set(spot[0] * VOXEL, spot[1] * VOXEL, 0);
      return m;
    };
    const torso = at(partMesh(v.torso, material), PART_AT.torso);
    const head = at(partMesh(v.head, material), PART_AT.head);
    const legL = at(partMesh(v.leg, material), PART_AT.legL);
    const legR = at(partMesh(v.leg, material), PART_AT.legR);
    const armL = at(partMesh(v.arm, material), PART_AT.armL);
    const armR = at(partMesh(v.arm, material), PART_AT.armR);
    body.add(torso, head, legL, legR, armL, armR);
    group.add(body);
    const label = nameSprite(info.nick);
    label.position.y = FIGURE_H + 0.3;
    group.add(label);
    group.position.set(info.x, info.y, info.z);
    body.rotation.y = info.yaw;
    body.rotation.order = 'YXZ'; // 누울 땐 먼저 눕히고(x) 그다음 돌린다(y) (#204)
    this.group.add(group);
    this.figures.set(info.idx, {
      info,
      group,
      body,
      label,
      torso,
      head,
      legL,
      legR,
      armL,
      armR,
      held: null,
      armor: [],
      target: { x: info.x, y: info.y, z: info.z, yaw: info.yaw, pitch: info.pitch, flags: 0 },
      cur: { x: info.x, y: info.y, z: info.z, yaw: info.yaw },
      walk: 0,
      guarding: false,
      sleeping: null,
      lastMove: 0,
      bubble: null,
      mount: null,
      riding: null,
      material,
      lum: 1,
    });
    if (info.riding) this.setMount(info.idx, info.riding);
    if (info.sleeping) this.setSleeping(info.idx, info.sleeping);
    if (info.held) this.setHeld(info.idx, info.held);
    if (info.equip) this.setEquip(info.idx, info.equip);
  }

  /** 입은 갑옷·방패 (M8-2): 부위마다 한 칸 두께 껍질을 자식으로 붙인다 (같은 재질 → 빛도 같이) */
  /** 그 사람 인형의 지금 자리 (보간된 값). 없으면 null — 펫이 주인을 따라가게 (#145) */
  positionOf(idx: number): { x: number; y: number; z: number } | null {
    const f = this.figures.get(idx);
    return f ? { x: f.cur.x, y: f.cur.y, z: f.cur.z } : null;
  }

  /** 겹치지 않게 (아빠 2026-11-05): (x, z) 에서 range 칸 안 다른 사람 몸 (누운 사람·탄 사람은 빼고). 서로 반씩 비킨다 */
  bodiesNear(x: number, z: number, range: number, out: SepBody[]): void {
    for (const f of this.figures.values()) {
      if (f.sleeping || f.mount || f.target.flags & FLAG_RIDING) continue;
      if (Math.abs(f.cur.x - x) > range || Math.abs(f.cur.z - z) > range) continue;
      out.push({ x: f.cur.x, y: f.cur.y, z: f.cur.z, r: 0.3, h: 1.8 });
    }
  }

  // ---------------------------------------------------------------- 낙타 뒷자리 (2026-11-07)

  /** 내가 모는 낙타 (Game 이 프레임마다): 뒤에 탄 친구를 내 낙타 뒷자리에 바로 붙여 그린다 */
  myCamel: { id: number; x: number; y: number; z: number; yaw: number } | null = null;

  /** 앞자리 위치에서 뒷자리 (낙타는 앞이 −z, 뒤는 +z 쪽) */
  private static behind(b: { x: number; y: number; z: number; yaw: number }): { x: number; y: number; z: number } {
    return { x: b.x + Math.sin(b.yaw) * CAMEL_BACK, y: b.y, z: b.z + Math.cos(b.yaw) * CAMEL_BACK };
  }

  /** 그 낙타를 모는 사람 (앞자리) */
  private driverOf(camelId: number): { x: number; y: number; z: number; yaw: number } | null {
    if (this.myCamel?.id === camelId) return this.myCamel;
    for (const f of this.figures.values()) if (f.riding?.dragon === 'camel' && !f.riding.back && f.riding.id === camelId) return f.cur;
    return null;
  }

  /** 내가 뒷자리에 탔을 때 내 발 자리 (앞 사람이 안 보이면 null) */
  passengerSeat(camelId: number): { x: number; y: number; z: number } | null {
    const d = this.driverOf(camelId);
    return d ? RemotePlayers.behind(d) : null;
  }

  /** 보고 있는 낙타를 모는 사람 번호 (뒤에 타기) — 낙타 몸통(앞자리 뒤 0.5, 높이 가운데)을 공 하나로 본다 */
  camelDriverAimed(eye: { x: number; y: number; z: number }, dir: { x: number; y: number; z: number }, reach: number): number | null {
    let best: number | null = null,
      bestT = Infinity;
    for (const f of this.figures.values()) {
      if (f.riding?.dragon !== 'camel' || f.riding.back) continue;
      const c = f.cur;
      const cx = c.x + Math.sin(c.yaw) * 0.5 - eye.x,
        cy = c.y - CAMEL_SEAT_Y * 0.5 - eye.y,
        cz = c.z + Math.cos(c.yaw) * 0.5 - eye.z;
      const t = cx * dir.x + cy * dir.y + cz * dir.z;
      if (t < 0 || t > reach + 1.3) continue;
      const d2 = cx * cx + cy * cy + cz * cz - t * t;
      if (d2 <= 1.3 * 1.3 && t < bestT) {
        bestT = t;
        best = f.info.idx;
      }
    }
    return best;
  }

  /** 침대에 눕기·일어나기 (#204) */
  setSleeping(idx: number, at: SleepInfo | null): void {
    const f = this.figures.get(idx);
    if (f) f.sleeping = at;
  }

  /** 🛡️ 막기 켜고 끄기 (#144) */
  /** 투명화 물약 (#245): 인형·이름표를 숨긴다 */
  setInvisible(idx: number, on: boolean): void {
    const f = this.figures.get(idx);
    if (f) f.group.visible = !on;
  }

  setGuarding(idx: number, on: boolean): void {
    const f = this.figures.get(idx);
    if (f) f.guarding = on;
  }

  setEquip(idx: number, parts: Record<string, string | null>): void {
    const f = this.figures.get(idx);
    if (!f) return;
    for (const m of f.armor) {
      m.parent?.remove(m);
      m.geometry.dispose();
    }
    f.armor = [];
    const eq = sanitizeEquipment(COMBAT, parts);
    f.info.equip = eq;
    const v = armorVoxels(eq);
    const torso = f.torso;
    const attach = (parent: THREE.Object3D | undefined, voxels: readonly Voxel[]) => {
      if (!parent || voxels.length === 0) return;
      const mesh = partMesh(voxels, f.material);
      parent.add(mesh);
      f.armor.push(mesh);
    };
    attach(f.head, v.head);
    attach(torso, v.torso);
    attach(f.armL, v.armL);
    attach(f.armR, v.armR);
    attach(f.legL, v.legL);
    attach(f.legR, v.legR);
    if (eq.shield) attach(f.armL, shieldVoxels());
  }

  /** 오른손에 든 것 (#96): 아이콘을 작은 판으로 손끝에 붙인다. 팔과 함께 흔들린다 */
  setHeld(idx: number, item: string | null): void {
    const f = this.figures.get(idx);
    if (!f) return;
    if (f.held) {
      f.armR.remove(f.held);
      f.held.geometry.dispose();
      const mat = f.held.material as THREE.MeshBasicMaterial;
      mat.map?.dispose();
      mat.dispose();
      f.held = null;
    }
    f.info.held = item;
    if (!item || !this.iconOf) return;
    const canvas = this.iconOf(item);
    if (!canvas) return;
    const tex = new THREE.CanvasTexture(canvas);
    tex.minFilter = THREE.LinearFilter;
    tex.magFilter = THREE.NearestFilter;
    const mesh = new THREE.Mesh(new THREE.PlaneGeometry(0.42, 0.42), new THREE.MeshBasicMaterial({ map: tex, transparent: true, alphaTest: 0.2, side: THREE.DoubleSide }));
    // 팔 축(어깨)에서 손끝(-11칸) 앞쪽. 조금 바깥·앞으로 기울여 정면·옆에서 다 보인다
    mesh.position.set(1.5 * VOXEL, -11 * VOXEL, -3 * VOXEL);
    mesh.rotation.set(-0.35, 0.45, 0);
    f.armR.add(mesh);
    f.held = mesh;
  }

  /** 드래곤 타기/내리기 (M6-4): 인형 발 아래에 어른 드래곤을 붙인다 */
  setMount(idx: number, riding: RidingInfo | null): void {
    const f = this.figures.get(idx);
    if (!f) return;
    if (f.mount) {
      f.body.remove(f.mount);
      f.mount = null;
    }
    f.riding = riding;
    if (riding && !riding.back) {
      const m = mountMesh(riding.dragon, riding.id); // 드래곤 또는 말 — 말은 제 털색 (#166·#177)
      const seat = mountSeat(riding.dragon);
      m.material = f.material; // 탄 드래곤도 같은 빛을 받는다
      m.position.y = -seat.seatY;
      m.rotation.y = seat.turn;
      f.body.add(m);
      f.mount = m;
    }
  }

  /** 머리 위 말풍선 (채팅, 3초) */
  say(idx: number, text: string, seconds = 3): void {
    const f = this.figures.get(idx);
    if (!f) return;
    this.clearBubble(f);
    const sprite = nameSprite(text, 'rgba(255,255,255,0.92)');
    (sprite.material as THREE.SpriteMaterial).color.setHex(0x222233);
    sprite.position.y = FIGURE_H + 0.8;
    f.group.add(sprite);
    f.bubble = { sprite, until: performance.now() + seconds * 1000 };
  }

  private clearBubble(f: Figure): void {
    if (!f.bubble) return;
    f.group.remove(f.bubble.sprite);
    f.bubble.sprite.material.map?.dispose();
    f.bubble.sprite.material.dispose();
    f.bubble = null;
  }

  remove(idx: number): void {
    const f = this.figures.get(idx);
    if (!f) return;
    this.clearBubble(f);
    this.setMount(idx, null); // 공유 지오메트리는 dispose 하지 않는다
    this.group.remove(f.group);
    f.material.dispose(); // 여섯 부위가 같이 쓰는 재질은 여기서 한 번만
    f.group.traverse((o) => {
      if (o instanceof THREE.Mesh) {
        o.geometry.dispose();
      }
      if (o instanceof THREE.Sprite) {
        o.material.map?.dispose();
        o.material.dispose();
      }
    });
    this.figures.delete(idx);
  }

  /** 지금 보이는 사람들의 번호 (세계 전환 때 전부 지우기용) */
  indices(): number[] {
    return [...this.figures.keys()];
  }

  nickOf(idx: number): string | undefined {
    return this.figures.get(idx)?.info.nick;
  }

  /** 서버 위치 묶음. 내 번호는 건너뛴다 */
  setState(list: readonly PlayerStateEntry[], myIdx: number): void {
    for (const s of list) {
      if (s.idx === myIdx) continue;
      const f = this.figures.get(s.idx);
      if (!f) continue;
      f.target.x = s.x;
      f.target.y = s.y;
      f.target.z = s.z;
      f.target.yaw = s.yaw;
      f.target.pitch = s.pitch;
      f.target.flags = s.flags;
    }
  }

  /**
   * light 를 주면 인형이 서 있는 칸의 빛을 받아 밝아지고 어두워진다 (#86).
   * 동굴에서는 어둡고 횃불 옆에서는 따뜻해진다 — 블록과 같은 곡선을 쓴다. 안 주면 늘 밝다
   */
  update(dt: number, light?: { get(x: number, y: number, z: number): number }, skyLight = 1): void {
    const k = 1 - Math.exp(-dt * 14); // 약 70ms 시간 상수
    for (const f of this.figures.values()) {
      const c = f.cur,
        t = f.target;
      const dx = t.x - c.x,
        dz = t.z - c.z;
      c.x += dx * k;
      c.y += (t.y - c.y) * k;
      c.z += dz * k;
      let dyaw = t.yaw - c.yaw;
      dyaw = Math.atan2(Math.sin(dyaw), Math.cos(dyaw));
      c.yaw += dyaw * k;
      if (f.riding?.back) {
        // 낙타 뒷자리 (2026-11-07): 앞 사람(나면 내 자리) 바로 뒤에 붙인다 — 따로 따라오면 달릴 때 벌어진다
        const d = this.driverOf(f.riding.id);
        if (d) {
          const b = RemotePlayers.behind(d);
          c.x = b.x;
          c.y = b.y;
          c.z = b.z;
          c.yaw = d.yaw;
        }
      }
      f.group.position.set(c.x, c.y, c.z);
      f.body.rotation.y = c.yaw;
      f.head.rotation.x = -t.pitch * 0.6;
      const speed = Math.hypot(dx, dz) * 14;
      if (speed > 0.3) f.walk += dt * Math.min(12, speed * 2.2);
      const riding = (t.flags & FLAG_RIDING) !== 0;
      const swing = speed > 0.3 && !riding ? Math.sin(f.walk) * 0.55 : 0; // 어깨·엉덩이가 축이라 전보다 작게
      f.legL.rotation.x = swing;
      f.legR.rotation.x = -swing;
      // 막는 중이면 왼팔을 앞으로 올려 방패를 세운다 (#144)
      f.armL.rotation.x = f.guarding ? -1.3 : -swing;
      f.armL.rotation.y = f.guarding ? 0.35 : 0;
      f.armR.rotation.x = swing;
      // 타면 앉는다 (#192, 아들 2026-10-19 "탈 때 서 있지 말고 앉게"): 다리를 앞으로 접고 팔은 고삐 잡듯 조금 앞으로,
      // 엉덩이가 탈것 등(발 높이)에 오도록 몸 부위를 다리 길이만큼 내린다. 탈것 메시는 body 의 자식이라 그대로 둔다
      const sit = riding && (f.mount !== null || f.riding?.back === true); // 낙타 뒷자리도 앉는다
      if (sit) {
        f.legL.rotation.x = f.legR.rotation.x = SIT_LEG;
        f.armR.rotation.x = SIT_ARM;
        if (!f.guarding) f.armL.rotation.x = SIT_ARM;
      }
      const drop = sit ? SIT_DROP : 0;
      f.torso.position.y = PART_AT.torso[1] * VOXEL - drop;
      f.head.position.y = PART_AT.head[1] * VOXEL - drop;
      f.armL.position.y = PART_AT.armL[1] * VOXEL - drop;
      f.armR.position.y = PART_AT.armR[1] * VOXEL - drop;
      f.legL.position.y = PART_AT.legL[1] * VOXEL - drop;
      f.legR.position.y = PART_AT.legR[1] * VOXEL - drop;
      const sneak = (t.flags & FLAG_SNEAK) !== 0;
      f.body.scale.y = sneak ? 0.85 : 1;
      f.label.position.y = (sneak ? FIGURE_H * 0.85 : FIGURE_H) - drop + 0.3;
      if (f.sleeping) {
        // 침대에 누움 (#204): 발은 발치 끝, 머리는 머리판 쪽, 등을 대고(x 로 90° 눕힘) 팔다리는 곧게
        const [sdx, sdz] = DOOR_DIR[f.sleeping.facing]!;
        c.x = f.sleeping.x;
        c.y = f.sleeping.y;
        c.z = f.sleeping.z;
        f.group.position.set(c.x - sdx * 0.95, c.y + 0.12, c.z - sdz * 0.95);
        f.body.rotation.set(Math.PI / 2, Math.atan2(sdx, sdz), 0);
        f.head.rotation.x = 0;
        f.legL.rotation.x = f.legR.rotation.x = f.armL.rotation.x = f.armR.rotation.x = 0;
        f.armL.rotation.y = 0;
        f.label.position.y = 0.9;
      } else f.body.rotation.x = 0;
      if (light) {
        // 가슴 높이 칸의 빛. 한 칸 넘어갈 때 뚝 끊기지 않게 부드럽게 따라간다
        const lum = lightColor(light.get(Math.floor(c.x), Math.floor(c.y + 1), Math.floor(c.z)), skyLight, TINT);
        f.lum += (lum - f.lum) * k;
        f.material.color.copy(TINT).multiplyScalar(f.lum);
      }
      if (f.bubble && performance.now() > f.bubble.until) this.clearBubble(f);
    }
  }

  dispose(): void {
    for (const idx of [...this.figures.keys()]) this.remove(idx);
  }
}
