/**
 * 작은 효과음 (M6-1): 파일 없이 Web Audio 로 합성. 경험치 구슬 "딩"(음높이 흔들림)과 레벨업.
 * 브라우저가 소리를 막으면(사용자 입력 전) 조용히 넘어간다.
 */
let ctx: AudioContext | null = null;
/** 연출용 흔들림 (규칙 2 의 Math.random 금지는 지형·규칙 코드용 — 여기서도 시드 xorshift 로 통일) */
let rs = 0x9e3779b9;
function rnd(): number {
  rs ^= rs << 13;
  rs ^= rs >>> 17;
  rs ^= rs << 5;
  return (rs >>> 0) / 4294967296;
}

function audio(): AudioContext | null {
  try {
    if (!ctx) ctx = new (window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext)();
    if (ctx.state === 'suspended') void ctx.resume();
    return ctx;
  } catch {
    return null;
  }
}

function tone(freq: number, at: number, dur: number, gain = 0.12, type: OscillatorType = 'sine'): void {
  const c = audio();
  if (!c) return;
  const o = c.createOscillator();
  const g = c.createGain();
  o.type = type;
  o.frequency.setValueAtTime(freq, at);
  g.gain.setValueAtTime(0, at);
  g.gain.linearRampToValueAtTime(gain, at + 0.01);
  g.gain.exponentialRampToValueAtTime(0.0005, at + dur);
  o.connect(g).connect(c.destination);
  o.start(at);
  o.stop(at + dur + 0.02);
}

/** 경험치 구슬 흡수: 마인크래프트 느낌의 짧은 "딩", 음높이가 조금씩 다르다 */
export function ding(pitchJitter = 0.25): void {
  const c = audio();
  if (!c) return;
  const base = 1200 * (1 + (rnd() * 2 - 1) * pitchJitter);
  tone(base, c.currentTime, 0.14, 0.08);
  tone(base * 2, c.currentTime, 0.08, 0.03);
}

/** 레벨업: 짧은 상승 아르페지오 */
export function levelUp(): void {
  const c = audio();
  if (!c) return;
  const t = c.currentTime;
  for (const [i, f] of [523.25, 659.25, 783.99, 1046.5].entries()) tone(f, t + i * 0.09, 0.22, 0.1, 'triangle');
}

/** 드래곤 빔 (M6-5): 낮게 울리다 쓸려 올라가는 소리. 세기(1~5)가 클수록 굵고 길다 */
export function beam(power = 1): void {
  const c = audio();
  if (!c) return;
  const t = c.currentTime;
  const p = Math.max(1, Math.min(5, power));
  const o = c.createOscillator();
  const g = c.createGain();
  o.type = 'sawtooth';
  o.frequency.setValueAtTime(90 + 20 * p, t);
  o.frequency.exponentialRampToValueAtTime(400 + 160 * p, t + 0.25);
  o.frequency.exponentialRampToValueAtTime(140 + 30 * p, t + 0.9 + 0.1 * p);
  g.gain.setValueAtTime(0, t);
  g.gain.linearRampToValueAtTime(0.05 + 0.015 * p, t + 0.05);
  g.gain.exponentialRampToValueAtTime(0.0005, t + 1.0 + 0.1 * p);
  o.connect(g).connect(c.destination);
  o.start(t);
  o.stop(t + 1.2 + 0.1 * p);
  tone(1600 + 200 * p, t, 0.12, 0.03); // 시작 순간의 반짝
}

/** 맞았다 (M7-1): 낮고 둔탁한 '퍽' */
export function hurt(): void {
  const c = audio();
  if (!c) return;
  const t = c.currentTime;
  tone(140, t, 0.12, 0.12, 'square');
  tone(90, t + 0.02, 0.18, 0.1, 'triangle');
}

/** 몹을 때렸다 (M7-2 #94): 짧은 '탁' */
export function hit(): void {
  const c = audio();
  if (!c) return;
  const t = c.currentTime;
  tone(520 + rnd() * 80, t, 0.05, 0.1, 'square');
  tone(250, t + 0.01, 0.08, 0.08, 'triangle');
}

/** 보스가 깨어나거나 부하를 부른다 (M7-4): 낮게 으르렁 */
export function roar(): void {
  const c = audio();
  if (!c) return;
  const t = c.currentTime;
  tone(70, t, 0.45, 0.18, 'sawtooth');
  tone(95, t + 0.08, 0.4, 0.12, 'square');
  tone(55, t + 0.2, 0.5, 0.14, 'triangle');
}

/** 마을 종 (M7-5): 우민이 온다. 세 번 울린다 */
export function bell(): void {
  const c = audio();
  if (!c) return;
  const t = c.currentTime;
  for (let i = 0; i < 3; i++) {
    tone(880, t + i * 0.55, 0.5, 0.12, 'sine');
    tone(1320, t + i * 0.55, 0.35, 0.05, 'triangle');
  }
}

/** 방어전 패배: 내려가는 세 음 */
export function lose(): void {
  const c = audio();
  if (!c) return;
  const t = c.currentTime;
  tone(392, t, 0.3, 0.12, 'square');
  tone(330, t + 0.3, 0.3, 0.12, 'square');
  tone(262, t + 0.6, 0.6, 0.12, 'square');
}

/** 크리퍼 폭발 (M7-2): 낮은 '쿵' + 잡음 */
export function explosion(): void {
  const c = audio();
  if (!c) return;
  const t = c.currentTime;
  tone(60, t, 0.5, 0.2, 'sawtooth');
  tone(38, t + 0.02, 0.7, 0.16, 'square');
  const buf = c.createBuffer(1, Math.floor(c.sampleRate * 0.35), c.sampleRate);
  const d = buf.getChannelData(0);
  for (let i = 0; i < d.length; i++) d[i] = (rnd() * 2 - 1) * (1 - i / d.length);
  const src = c.createBufferSource();
  const g = c.createGain();
  src.buffer = buf;
  g.gain.setValueAtTime(0.18, t);
  g.gain.exponentialRampToValueAtTime(0.0005, t + 0.35);
  src.connect(g).connect(c.destination);
  src.start(t);
}

/** 폭죽 발사 (#211): 휘파람처럼 올라가는 소리 */
export function fireworkLaunch(): void {
  const c = audio();
  if (!c) return;
  const t = c.currentTime;
  const o = c.createOscillator();
  const g = c.createGain();
  o.type = 'sine';
  o.frequency.setValueAtTime(400, t);
  o.frequency.exponentialRampToValueAtTime(1400, t + 0.9);
  g.gain.setValueAtTime(0.0001, t);
  g.gain.exponentialRampToValueAtTime(0.05, t + 0.05);
  g.gain.exponentialRampToValueAtTime(0.0005, t + 1.0);
  o.connect(g).connect(c.destination);
  o.start(t);
  o.stop(t + 1.05);
}
/** 폭죽 터짐 (#211): 짧은 "펑" + 반짝 */
export function fireworkPop(): void {
  const c = audio();
  if (!c) return;
  const t = c.currentTime;
  const buf = c.createBuffer(1, Math.floor(c.sampleRate * 0.25), c.sampleRate);
  const d = buf.getChannelData(0);
  for (let i = 0; i < d.length; i++) d[i] = (rnd() * 2 - 1) * (1 - i / d.length) ** 2;
  const src = c.createBufferSource();
  const g = c.createGain();
  src.buffer = buf;
  g.gain.setValueAtTime(0.14, t);
  g.gain.exponentialRampToValueAtTime(0.0005, t + 0.25);
  src.connect(g).connect(c.destination);
  src.start(t);
  tone(1800 + rnd() * 600, t + 0.05, 0.3, 0.03, 'triangle');
  tone(2400 + rnd() * 600, t + 0.12, 0.3, 0.025, 'triangle');
}

/** 낚시 입질 (2026-11-06): 물이 퐁! 하고 튀는 소리 — 높은 음이 빠르게 떨어진다 */
export function splash(): void {
  const c = audio();
  if (!c) return;
  const t = c.currentTime;
  const o = c.createOscillator();
  const g = c.createGain();
  o.type = 'triangle';
  o.frequency.setValueAtTime(900, t);
  o.frequency.exponentialRampToValueAtTime(180, t + 0.18);
  g.gain.setValueAtTime(0.0001, t);
  g.gain.linearRampToValueAtTime(0.16, t + 0.01);
  g.gain.exponentialRampToValueAtTime(0.0005, t + 0.22);
  o.connect(g).connect(c.destination);
  o.start(t);
  o.stop(t + 0.25);
  tone(1500 + rnd() * 300, t + 0.03, 0.06, 0.04);
}
