import { DOOR_DIR, RAIL_DIRS, SLAB_DOUBLE, SLAB_TOP, type BlockRegistry } from '@dragon-village/shared';
import { CONNECTED_BLOCKS, connectTable } from './connected';
import { LAYER_CUTOUT, LAYER_NONE, LAYER_OPAQUE, LAYER_TRANSLUCENT, type MeshBlockInfo } from './meshTypes';

/**
 * 블록 레지스트리 + 텍스처 레이어 표 → 워커용 평탄 배열 (인덱스 = 블록 번호).
 * 없는 텍스처는 'missing' 레이어(0)로.
 */
export function buildMeshBlockInfo(registry: BlockRegistry, textureIndex: ReadonlyMap<string, number>): MeshBlockInfo[] {
  const missing = textureIndex.get('missing') ?? 0;
  const layerOf = (name: string): number => textureIndex.get(name) ?? missing;

  return registry.defs.map((d): MeshBlockInfo => {
    if (d.id === 'air' || !d.textures) {
      return { layer: LAYER_NONE, opaque: false, castAO: false, sameCull: false, tex: [0, 0, 0, 0, 0, 0], fluidKind: 0, fluidHeight: 0, panel: null, torch: null, egg: false, cross: false, bed: null, sign: false, rail: null };
    }
    const translucent = d.fluid === 'water' || d.id === 'ice';
    // 용암은 solid=false 지만 마인크래프트처럼 불투명하게 그린다
    const opaque = (d.solid && !d.transparent) || d.fluid === 'lava';
    const layer = translucent ? LAYER_TRANSLUCENT : opaque ? LAYER_OPAQUE : LAYER_CUTOUT;
    const [top, side, bottom] = d.textures;
    const s = layerOf(side);
    // 문(#71): 닫힌 문은 놓은 사람 쪽 가장자리에, 열린 문은 왼쪽(경첩) 가장자리에 붙은 얇은 판
    let panel: MeshBlockInfo['panel'] = null;
    if (d.door) {
      const [fx, fz] = DOOR_DIR[d.door.facing]!;
      if (!d.door.open) panel = [fx !== 0 ? 0 : 2, fx < 0 || fz < 0 ? 1 : 0];
      else {
        // 열린 문은 경첩 쪽 가장자리에 붙는다 (왼쪽 0 / 오른쪽 1, 결정 #83)
        const hx = d.door.hinge ? -fz : fz,
          hz = d.door.hinge ? fx : -fx;
        panel = [hx !== 0 ? 0 : 2, hx < 0 || hz < 0 ? 0 : 1];
      }
    }
    return {
      panel,
      torch: d.torch ? d.torch.wall : null,
      egg: d.shape === 'egg',
      cross: d.shape === 'cross',
      bed: d.bed ? [d.bed.facing, d.bed.head ? 1 : 0] : null,
      sign: d.shape === 'sign',
      table: d.shape === 'table',
      campfire: d.shape === 'campfire' ? { log: s, end: layerOf('campfire_log_end'), fire: d.lightEmit > 0 ? layerOf('campfire_fire') : -1 } : null,
      rail: d.rail ? RAIL_DIRS.indexOf(d.rail.dir) : null,
      stairs: d.stairs ? [d.stairs.facing, d.stairs.top ? 1 : 0] : null,
      fence: d.fence,
      gate: d.gate ? [d.gate.facing, d.gate.open ? 1 : 0] : null,
      trap: d.trap ? d.trap.facing * 4 + (d.trap.top ? 2 : 0) + (d.trap.open ? 1 : 0) : null,
      ladder: d.ladder ? d.ladder.facing : null,
      slab: d.slab && d.slab.kind !== SLAB_DOUBLE ? (d.slab.kind === SLAB_TOP ? 0xf0 : 0x0f) : null,
      connect: CONNECTED_BLOCKS.has(d.id) ? connectTable(side, (n) => textureIndex.get(n)) : null, // 유리끼리 맞닿은 쪽 테두리 없애기 (2026-11-09)
      layer,
      opaque,
      castAO: (opaque && !d.fluid) || d.id === 'leaves',
      sameCull: d.transparent,
      tex: [s, s, layerOf(top), layerOf(bottom), s, s],
      fluidKind: d.fluid === 'water' ? 1 : d.fluid === 'lava' ? 2 : 0,
      fluidHeight: d.fluid ? (8 - d.fluidLevel) / 9 : 0,
    };
  });
}
